# Code generated by Claude
"""The modules the orchestrator runs (src/orchestrator.py), each behind its own small interface so that any of them can be swapped.

    world = make_sim_world_model(model, data)                         # the knowledge base of src/world_model.py, filled from the simulator's ground truth (perception later)
    nav   = make_scripted_navigation(model, data, world)             # the existing scripted staging
    manip = make_scripted_manipulation(model, data, world, "left", home_q)   # scripted pick and place with mink through a few waypoints
    check = make_oracle_checker(model, data, world, manip["pad_pose"])        # sim ground truth (the VLM comes later)

World model: src/world_model.WorldModel. The modules read it only through object_pose(id) -> {"position": bottom centre (3,), "axis": the up axis (3,)} (a fixture's position is its top
centre), bench_top_z(), object_height(id) and stance(target). Which objects a manipulation segment acts on comes from the grounder (src/grounding.py): the segment handed to start() has
"grounded": {"manipulated": entry id, "destination": entry id (place only)}.

Navigation and manipulation modules share the protocol of a stage, plus a segment start and events:
    start(segment)  begin the segment (the orchestrator calls it once per attempt, on the tick the attempt starts). A manipulation segment comes with its grounded ids and, as in the paper
                    (E4), with "group_description" (the concatenated descriptions of its manipulation group: what a VLA reads as its task text) and "group_completion_criteria" (the final
                    segment's criterion). The scripted skill ignores both (it is driven by the primitive and the objects) and only keeps the text for its report.
    recover()       optional, manipulation only: begin the recovery of a failed step, the failing arm back to its zombie pose (design plan 8 D4 item 2); then step/done/error as for a segment. The
                    other arm is not commanded.
    step(obs)       -> the commands of this tick (a command, a list, or None)
    done()          -> bool, the segment's motion is finished
    error()         -> str or None, a failure message (the orchestrator stops the plan and reports it)
    phase()         -> str, what the module is doing now (shown in the viewer's status row)
    events()        -> list of events since the last call: "gripper_closed" (commanded closed, the fingers at rest for a short window, stopped short of fully closed: something between
                       them) and "gripper_opened" (manipulation only: commanded open, the fingers at rest at the open position; thresholds in PICK_PLACE_CFG: stall_speed_m_s, stall_dwell_s,
                       held_travel_range_m, open_reached_margin_m)
    observe(obs), resume(), report()   optional, as for a stage of src/sequential_policy.py

Completion checker: check(segment, event, obs, decides=False) -> {"passed": bool, "reason": str, "details": dict}, called after every gripper event; `decides` says whether the verdict decides (the segment's
last manipulation step at the event that ends its primitive) or is only logged. The oracle ignores it; the VLM checker (src/mpvi_vlm.py) calls the VLM only when it is true.

Scripted pick and place (PICK_PLACE_CFG, MINK_CFG in src/task_config.py): the pad centre goes through the waypoints of design plan 3.3 with the hand level, the approach along the
robot's forward direction. PICK: OVER (at the clearance height, a standoff back from the beaker), DOWN (to the grasp height), IN (the pad centre on the beaker's axis), CLOSE (8 N), UP
(the carry height, the beaker held). PLACE: OVER (the hotplate, at that height), DOWN (the beaker's bottom just above the plate), OPEN, BACK (a standoff out, the fingers clear of the
beaker), HOME (the pad centre to the home pose's, then the joints). The simulator's gravity compensation does not carry the beaker's weight, so the arm sags under it: a simple
correction integrates the measured pad pose error (the forward kinematics of the measured joints) into the waypoint path (PICK_PLACE_CFG sag_*). A waypoint ends when the measured pad centre is within tolerance and the arm is settled; a timeout or a mink
failure ends the plan with the reason.
"""

import math

import mujoco
import numpy as np
from scipy.spatial.transform import Rotation, Slerp

import mink

from src.mink_arm import MinkArm, pad_rotation
from src.rate_limit import min_jerk
from src.robot_helpers import arm_ids
from src.staging_source import make_staging_source
from src.task_beaker_hotplate import bench_top_z, check_success
from src.task_config import BEAKER_CFG, GRIP_FORCE_TABLE, MINK_CFG, PICK_PLACE_CFG, STAGING_CFG, SUCCESS_CFG, TASK_CFG
from src.world_model import SimGroundTruthSource, WorldModel


def _clip_norm(v, limit):
    """Scales a vector down to at most `limit` in length."""
    n = float(np.linalg.norm(v))
    return v if n <= limit else v * (limit / n)


# ----------------------------------------------------------------------------------------------------------
# World model
# ----------------------------------------------------------------------------------------------------------
def make_sim_world_model(model, data, task_cfg=TASK_CFG, beaker_cfg=BEAKER_CFG):
    """Builds the world model (the knowledge base) filled from the simulator's true state.

    Args:
        model (mujoco.MjModel): The task model.
        data (mujoco.MjData): The live simulation state (read at every refresh).
        task_cfg (dict): TASK_CFG, for the staging stance.
        beaker_cfg (dict): BEAKER_CFG, for the beaker's height and liquid.

    Returns:
        WorldModel: Refreshed once; every object_pose() call refreshes again.
    """
    world = WorldModel([SimGroundTruthSource(model, data, task_cfg, beaker_cfg)])
    world.refresh(data.time)
    return world


# ----------------------------------------------------------------------------------------------------------
# Navigation: the existing scripted staging
# ----------------------------------------------------------------------------------------------------------
def make_scripted_navigation(model, data, world, task_cfg=TASK_CFG, staging_cfg=STAGING_CFG):
    """Wraps the scripted staging (src/staging_source.py) as the navigation module.

    Args:
        model (mujoco.MjModel): The task model.
        data (mujoco.MjData): The live state.
        world (WorldModel): The world model; its stance() resolves the segment's target (an unknown target ends the plan).
        task_cfg (dict): TASK_CFG. Defaults to it.
        staging_cfg (dict): STAGING_CFG. Defaults to it.

    Returns:
        dict: The module (see the module docstring); "stage" is the staging stage itself.
    """
    stage = make_staging_source(model, data, task_cfg, staging_cfg)
    S = {"error": None}

    def start(segment):
        """Resolves the segment's target through the world model (a phrase such as "the beaker" gives the bench's stance); the staging itself always goes to the test task's stance, so
        any other stance ends the plan. A second navigation segment to the same stance finds the staging already done and ends at once."""
        try:
            S["stance"] = world.stance(segment["target"])
            if S["stance"] != {"xy": task_cfg["staging_xy"], "yaw": task_cfg["staging_yaw"], "pedestal_q": task_cfg["pedestal_q"]}:
                S["error"] = f"navigation: the scripted staging reaches only the test task's stance, not the one of {segment['target']!r}"
        except KeyError as e:
            S["error"] = f"navigation: {e.args[0]}"

    return {"name": "scripted staging", "stage": stage, "start": start, "step": stage["step"], "done": stage["done"],
            "error": lambda: S["error"] or stage["error"](), "phase": stage["phase"], "events": lambda: [], "observe": stage["observe"],
            "resume": stage["resume"], "report": stage["report"]}


# ----------------------------------------------------------------------------------------------------------
# Manipulation: scripted pick and place with mink
# ----------------------------------------------------------------------------------------------------------
def make_scripted_manipulation(model, data, world, side, home_q, task_cfg=TASK_CFG, cfg=PICK_PLACE_CFG, mink_cfg=MINK_CFG, force=None, carry_ref="hotplate"):
    """Builds the manipulation module: the pick and place primitives of one arm.

    Args:
        model (mujoco.MjModel): The task model.
        data (mujoco.MjData): The live state.
        world (WorldModel): The world model (object poses are read through it).
        side (str): The arm, "left" or "right".
        home_q (array-like): The arm's home pose (7 radians).
        task_cfg (dict): TASK_CFG, for the open finger travel. Defaults to it.
        cfg (dict): PICK_PLACE_CFG. Defaults to it.
        mink_cfg (dict): MINK_CFG. Defaults to it.
        force (float or None): The grip force per finger, newtons; None means the grip force table's value for the glass beaker. Defaults to None.
        carry_ref (str): The world-model id whose surface sets the carry height of a pick (the surface the next place goes to; LATER: take it from the plan's next place step).
            Defaults to "hotplate".

    Returns:
        dict: The module (see the module docstring), plus "pad_pose"() -> (position, rotation) of the pad centre from the measured joints and "arm" (the MinkArm).
    """
    ids = arm_ids(model, side)
    act_ids = ids["act"]                                     # the arm's 7 position actuators (start() has its own local "ids")
    arm = MinkArm(model, data, side, home_q, mink_cfg)
    open_g = task_cfg.get("finger_open", 0.044)
    force = GRIP_FORCE_TABLE["glass_beaker"] if force is None else force
    f1 = ids["finger_jnt"][0]
    fq, fv = int(model.jnt_qposadr[f1]), int(model.jnt_dofadr[f1])
    base = model.body("base_link").id
    home_q = np.asarray(home_q, float)
    C = {"p": np.zeros(3), "r": np.zeros(3)}                 # the sag correction: an integral of the measured pad pose error, added to the waypoint path
    S = {"steps": [], "i": 0, "t0": None, "error": None, "events": [], "started": False, "phase": "IDLE", "still": None, "grip": open_g, "ctx": {}, "ramp_k": 10 ** 9, "v_last": np.zeros(7)}

    def home_pad_pose():
        """The pad centre pose with the arm at its home joints (on a scratch copy of the state)."""
        d2 = mujoco.MjData(model)
        d2.qpos[:] = data.qpos
        d2.qpos[arm.qadr] = home_q
        mujoco.mj_kinematics(model, d2)
        return arm.pad_pose(d2)

    def commanded_pad_pose():
        """The pad centre pose with the arm at its last commanded joints (arm.q_cmd), on a scratch copy of the state."""
        d2 = mujoco.MjData(model)
        d2.qpos[:] = data.qpos
        d2.qpos[arm.qadr] = arm.q_cmd
        mujoco.mj_kinematics(model, d2)
        return arm.pad_pose(d2)

    def forward():
        """The robot's forward direction in the world (horizontal unit vector)."""
        f = data.xmat[base].reshape(3, 3)[:, 0].copy()
        f[2] = 0.0
        return f / np.linalg.norm(f)

    def fail(msg):
        S["error"] = msg
        print(f"[manipulation] FAILED: {msg}")

    def move(name, target, speed, R):
        return {"kind": "move", "name": name, "target": np.asarray(target, float), "speed": speed, "R": R}

    def plan_pick(obj):
        """The waypoints of a pick from the grounded object's pose now."""
        b = world.object_pose(obj)["position"]
        a = forward()
        _, R0 = arm.pad_pose(data)
        R = pad_rotation(a, R0[:, 0])
        frac = cfg["grasp_height_frac"]
        height = world.object_height(obj)
        hg = b[2] + frac * height
        hp = world.object_pose(carry_ref)["position"]
        z_clear = world.bench_top_z() + cfg["clearance_m"]
        z_carry = max(hp[2] + frac * height + cfg["carry_gap_m"], hg + 0.05)
        stand = b[:2] - a[:2] * cfg["standoff_m"]
        S["ctx"]["z_rise_ref"] = float(b[2])
        steps = [move("OVER", [*stand, z_clear], cfg["speed_m_s"], R), move("DOWN", [*stand, hg], cfg["slow_speed_m_s"], R),
                 move("IN", [b[0], b[1], hg], cfg["slow_speed_m_s"], R), {"kind": "close", "name": "CLOSE"},
                 move("UP", [b[0], b[1], z_carry], cfg["slow_speed_m_s"], R), {"kind": "held", "name": "CHECK"}]
        if S["ctx"].get("end_at_zombie"):                    # M074 (bench rectangle selection): the next step is a navigation step that moves, so the arm goes home holding the beaker, as the recovery does
            back = np.array([b[0], b[1], z_carry])
            back[:2] -= a[:2] * cfg["retreat_m"]
            hp_pose, hR = home_pad_pose()
            steps += [move("BACK", back, cfg["slow_speed_m_s"], R), move("HOME", hp_pose, cfg["speed_m_s"], hR), {"kind": "joints", "name": "HOME"}]
        return steps

    def plan_place(obj, dest):
        """The waypoints of a place from where the arm and the held object are now."""
        b = world.object_pose(obj)["position"]
        hp = world.object_pose(dest)["position"]
        p, R0 = arm.pad_pose(data)
        a = forward()
        R = pad_rotation(a, R0[:, 0])
        off = p - b                                          # the pad centre relative to the beaker's bottom centre in the hand (measured now)
        th = S["ctx"]["place_theta"]
        if th is None:
            raise ValueError("the place step has no place_theta_deg: the stance selection gives every place step its hand angle (M184)")
        # M183/M184: th is the hand turn the stance selection chose or searched for this place (radians, counter-clockwise seen from above)
        co, si = math.cos(th), math.sin(th)
        Rz = np.array([[co, -si, 0.0], [si, co, 0.0], [0.0, 0.0, 1.0]])
        R = Rz @ R                                           # the hand stays level and turns about the vertical axis through the beaker's centre: the beaker stays upright (the carry move turns it smoothly from the grasp angle)
        off = Rz @ off                                       # the pad centre turns round the beaker's axis with the hand
        a = Rz @ a                                           # so does the approach direction (the back-off goes out along it)
        over = np.array([hp[0] + off[0], hp[1] + off[1], p[2]])
        down = np.array([hp[0] + off[0], hp[1] + off[1], hp[2] + off[2] + cfg["setdown_gap_m"]])
        back = down.copy()
        back[:2] -= a[:2] * cfg["retreat_m"]
        hp_pose, hR = home_pad_pose()
        return [move("OVER", over, cfg["speed_m_s"], R), move("DOWN", down, cfg["slow_speed_m_s"], R), {"kind": "open", "name": "OPEN"},
                move("BACK", back, cfg["slow_speed_m_s"], R), move("HOME", hp_pose, cfg["speed_m_s"], hR), {"kind": "joints", "name": "HOME"}]

    def start(segment):
        """Plans the segment's primitive from the world as it is now."""
        prim = segment["primitive"]
        S.update(i=0, t0=None, error=None, events=[], started=True, still=None)
        S["ctx"]["primitive"] = prim
        S["ctx"]["task_text"] = {"group_description": segment.get("group_description"), "group_completion_criteria": segment.get("group_completion_criteria")}
        ids = segment.get("grounded") or {}
        S["ctx"]["obj"] = ids.get("manipulated")
        S["ctx"]["end_at_zombie"] = bool(segment.get("end_at_zombie"))
        S["ctx"]["place_theta"] = None if segment.get("place_theta_deg") is None else math.radians(float(segment["place_theta_deg"]))      # M184: no default angle (0 is the marginal angle); a place without one fails below
        if cfg["restart_from_commanded"]:                     # M195: the new skill continues from the ctrl that was applied on the previous tick, not from the measured joints (which lose the servo's holding offset under the beaker)
            arm.q_cmd = np.asarray(data.ctrl[act_ids], float).copy()
        else:
            S["q_prev"] = arm.q_cmd.copy() if cfg["skill_start_ramp"] else None      # M195: the command of the last tick, from which the ramp of the first tick of this skill starts
            arm.reset(data)
        C["p"], C["r"] = np.zeros(3), np.zeros(3)
        S["v_last"] = np.zeros(7)
        try:
            if S["ctx"]["obj"] is None:
                raise ValueError("the segment has no grounded object")
            S["steps"] = plan_pick(S["ctx"]["obj"]) if prim == "pick" else plan_place(S["ctx"]["obj"], ids["destination"]) if prim == "place" else None
        except Exception as e:                                # noqa: BLE001 - any planning failure ends the plan with its message
            fail(f"{prim}: planning failed: {type(e).__name__}: {e}")
            return
        if S["steps"] is None:
            fail(f"unknown primitive {prim!r}")
        S["phase"] = S["steps"][0]["name"] if S["steps"] else "IDLE"
        print(f"[manipulation] {prim}: " + " -> ".join(s["name"] for s in S["steps"]))

    def recover():
        """Begins the recovery of a failed step: the failing arm goes back to its zombie pose (the home pose), nothing else moves (the other arm is not commanded).

        The fingers are opened first when the world model says this hand holds nothing (a hand that holds something keeps its grip); then the pad centre backs off along the robot's forward
        direction by the retreat distance, goes to the zombie pose's pad centre, and the joints go to the zombie pose.
        """
        S.update(i=0, t0=None, error=None, events=[], started=True, still=None)
        S["ctx"]["primitive"] = "recover"
        arm.reset(data)
        C["p"], C["r"] = np.zeros(3), np.zeros(3)
        S["v_last"] = np.zeros(7)
        p, R0 = arm.pad_pose(data)
        a = forward()
        R = pad_rotation(a, R0[:, 0])
        back = p.copy()
        back[:2] -= a[:2] * cfg["retreat_m"]
        hp_pose, hR = home_pad_pose()
        steps = [] if world.held_by(side) else [{"kind": "open", "name": "OPEN"}]
        S["steps"] = steps + [move("BACK", back, cfg["slow_speed_m_s"], R), move("HOME", hp_pose, cfg["speed_m_s"], hR), {"kind": "joints", "name": "HOME"}]
        S["phase"] = S["steps"][0]["name"]
        print(f"[manipulation] recover (zombie pose): " + " -> ".join(s["name"] for s in S["steps"]))

    def command(grip=None):
        """The arms command: the joint command, and the gripper's (kept every tick: a plain travel would reset the force limit)."""
        g = S["grip"] if grip is None else grip
        return {"mode": "arms", "arm_targets": {side: [float(v) for v in arm.q_cmd]}, "gripper": {side: g}}

    def settled(t, dwell):
        """True once the arm's joints have been slower than the settle speed for `dwell` seconds."""
        if float(np.max(np.abs(data.qvel[arm.vadr]))) < cfg["settle_speed_rad_s"]:
            if S["still"] is None:
                S["still"] = t
            return t - S["still"] >= dwell
        S["still"] = None
        return False

    def step_inner(obs):
        """One tick of the current waypoint (before the phase-start velocity ramp of step())."""
        if not S["started"] or S["error"] or S["i"] >= len(S["steps"]):
            return None
        t = obs["time"]
        st = S["steps"][S["i"]]
        S["phase"] = st["name"]
        if S["t0"] is None:
            S["t0"], S["still"] = t, None
            if st["kind"] == "move":
                if cfg["restart_from_commanded"]:                   # M195: the reference starts where the command is (its pad pose, less the sag correction that is added back to every target), not at the measured pad pose
                    p0, R0 = commanded_pad_pose()
                    p0 = p0 - C["p"]
                    R0 = (Rotation.from_rotvec(C["r"]).inv() * Rotation.from_matrix(R0)).as_matrix()
                else:
                    p0, R0 = arm.pad_pose(data)
                dist = float(np.linalg.norm(st["target"] - p0)) if st["kind"] == "move" else 0.0
                ang = float(np.linalg.norm(Rotation.from_matrix(R0.T @ st["R"]).as_rotvec()))
                T = max(cfg["min_move_s"], dist / st["speed"], ang / cfg["turn_rad_s"])
                if cfg["joint_limited_duration"]:                  # M194: never plan the move faster than its farthest-travelling joint can follow at the solver's speed limit
                    us = np.linspace(0.0, 1.0, cfg["arc_points"] + 1)
                    sl = Slerp([0.0, 1.0], Rotation.from_matrix([R0, st["R"]]))
                    try:
                        arc, end = arm.joint_arc(data, p0 + np.outer(us, st["target"] - p0), sl(us).as_matrix())
                        st["arc"], st["end"] = float(arc.max()), float(end.max())
                    except mink.NoSolutionFound as e:
                        print(f"[manipulation] {st['name']}: the dry run found no solution ({e})")
                        st["arc"] = st["end"] = 0.0                # the move itself reports the failure, with its own message
                    T = max(T, cfg["min_jerk_peak_factor"] * st["arc"] / arm.cfg["max_joint_speed"])
                st.update(p0=p0, slerp=Slerp([0.0, 1.0], Rotation.from_matrix([R0, st["R"]])), T=T)
            elif st["kind"] == "joints":
                st["q0"] = arm.q_cmd.copy()
                st["T"] = max(cfg["min_move_s"], float(np.max(np.abs(home_q - st["q0"]))) / 0.3)
            print(f"[manipulation] {st['name']} ({st['kind']}) at t={t:.2f} s" + (f", {st['T']:.1f} s planned" + (f" (joint arc {st['arc']:.2f} rad, endpoint {st['end']:.2f} rad)" if "arc" in st else "") if "T" in st else ""))
        el = t - S["t0"]
        kind = st["kind"]
        advance = False
        if kind == "move":
            u = min(el / st["T"], 1.0)
            s = min_jerk(u)
            p_ref, R_ref = st["p0"] + (st["target"] - st["p0"]) * s, st["slerp"](s).as_matrix()
            p_now, R_now = arm.pad_pose(data)                          # the measured pad pose: what the arm really does under the beaker's weight
            dt = obs["timestep"] * obs["steps_per_frame"]
            C["p"] = _clip_norm(C["p"] + cfg["sag_gain_per_s"] * (p_ref - p_now) * dt, cfg["sag_max_m"])
            C["r"] = _clip_norm(C["r"] + cfg["sag_gain_per_s"] * Rotation.from_matrix(R_ref @ R_now.T).as_rotvec() * dt, cfg["sag_max_rad"])
            try:
                arm.step(data, p_ref + C["p"], (Rotation.from_rotvec(C["r"]) * Rotation.from_matrix(R_ref)).as_matrix())
            except mink.NoSolutionFound:
                fail(f"{st['name']}: mink found no solution (joint limits or collision avoidance leave no motion)")
                return None
            p, R = arm.pad_pose(data)
            err = float(np.linalg.norm(p - st["target"]))
            ang = float(np.linalg.norm(Rotation.from_matrix(R.T @ st["R"]).as_rotvec()))
            if u >= 1.0 and err < cfg["tol_m"] and ang < cfg["tol_rad"] and settled(t, cfg["settle_dwell_s"]):
                advance = True
            elif el > cfg["timeout_factor"] * st["T"] + cfg["timeout_extra_s"]:
                fail(f"{st['name']}: not reached after {el:.1f} s: {1000 * err:.1f} mm and {math.degrees(ang):.1f} deg from the waypoint")
                return None
            out = command()
        elif kind == "joints":
            u = min(el / st["T"], 1.0)
            arm.q_cmd = st["q0"] + (home_q - st["q0"]) * min_jerk(u)
            err = float(np.max(np.abs(data.qpos[arm.qadr] - home_q)))
            if u >= 1.0 and err < 0.02 and settled(t, cfg["settle_dwell_s"]):
                advance = True
            elif el > cfg["timeout_factor"] * st["T"] + cfg["timeout_extra_s"]:
                fail(f"{st['name']}: the arm did not settle at home after {el:.1f} s (largest joint error {err:.3f} rad)")
                return None
            out = command()
        elif kind in ("close", "open"):
            closing = kind == "close"
            S["grip"] = {"position": 0.0, "max_force": float(force)} if closing else open_g
            out = command()
            travel, speed = float(data.qpos[fq]), abs(float(data.qvel[fv]))
            stalled = speed < cfg["stall_speed_m_s"]
            S["still"] = (S["still"] if S["still"] is not None else t) if stalled else None
            done_stalled = S["still"] is not None and t - S["still"] >= cfg["stall_dwell_s"]
            if not closing and travel < open_g - cfg["open_reached_margin_m"]:
                done_stalled = False                               # the open event needs the open position reached (design plan 8 D4), not only fingers at rest
            if el >= cfg["close_min_s"] and done_stalled:
                if closing:
                    lo, hi = cfg["held_travel_range_m"]
                    if travel < lo:
                        fail(f"CLOSE: empty grasp, the fingers closed to {1000 * travel:.1f} mm travel with nothing between them")
                        return None
                    if travel > hi:
                        fail(f"CLOSE: the gripper did not close (finger travel {1000 * travel:.1f} mm)")
                        return None
                    S["ctx"]["z_at_close"] = float(world.object_pose(S["ctx"]["obj"])["position"][2])
                S["events"].append("gripper_closed" if closing else "gripper_opened")
                if not closing:
                    C["p"], C["r"] = np.zeros(3), np.zeros(3)      # the beaker's weight is off the arm
                advance = True
            elif el > (cfg["close_timeout_s"] if closing else cfg["open_timeout_s"]):
                fail(f"{st['name']}: the gripper did not stop within {el:.1f} s")
                return None
        elif kind == "held":
            rise = float(world.object_pose(S["ctx"]["obj"])["position"][2]) - S["ctx"]["z_rise_ref"]        # a LOGGED measurement of the lift (sim ground truth): it no longer decides, the drop monitor does
            S["ctx"]["lift_rise_m"] = rise                                                                  # (src/mpvi_monitors.py, decisions-log M044)
            print(f"[manipulation] UP: the beaker rose {1000 * rise:.0f} mm [logged only]")
            advance = True
            out = command()
        if advance:
            S["i"], S["t0"], S["still"] = S["i"] + 1, None, None
        return out

    def step(obs):
        """One tick: step_inner, then the phase-start ramp (M195): in the first N ticks of every phase (and of a skill, from the last command, see start()) the speed of each arm joint is
        capped by the minimum-jerk envelope max_joint_speed * min_jerk(t / phase_start_ramp_s), t = time since the phase start at the end of this tick, so the commanded velocity and
        acceleration start from zero and the solver's first solution of a new phase cannot jump the command. Not applied mid-phase; a cap that does not bind changes nothing, so it is
        simply left on for the N ticks. N = ceil(phase_start_ramp_s / dt); 0 s turns the ramp off."""
        dt = obs["timestep"] * obs["steps_per_frame"]
        q_before = arm.q_cmd.copy()
        if S.get("q_prev") is not None:                            # first tick after arm.reset at a skill start: the ramp runs from the last command, so the snap to the measured joints is spread over the ramp
            q_before, S["q_prev"] = S["q_prev"], None
        if S["started"] and S["error"] is None and S["i"] < len(S["steps"]) and S["t0"] is None:
            S["ramp_k"] = 0                                        # a new phase starts on this tick
        out = step_inner(obs)
        if out is None:
            return None
        v = (arm.q_cmd - q_before) / dt
        n_ramp = math.ceil(round(cfg["phase_start_ramp_s"] / dt, 6))
        if S["ramp_k"] < n_ramp:
            env = MINK_CFG["max_joint_speed"] * min_jerk((S["ramp_k"] + 1) * dt / cfg["phase_start_ramp_s"])
            v_cap = v * min(1.0, env / max(float(np.max(np.abs(v))), 1e-12)) if mink_cfg.get("uniform_speed_scaling") else np.clip(v, -env, env)       # uniform_speed_scaling: one factor for all joints (the direction is kept)
            if np.any(v_cap != v):
                arm.q_cmd = q_before + v_cap * dt
                v = v_cap
                out = command()
        S["ramp_k"] += 1
        S["v_last"] = v
        return out

    def done():
        return S["started"] and S["error"] is None and S["i"] >= len(S["steps"])

    def end_report():
        """What the skill that just ended left behind, for the log (not part of any check): after a place the arm's return to home; nothing for a pick (it ends holding at the carry height)."""
        if S["ctx"].get("primitive") != "place":
            return None
        err = float(np.max(np.abs(data.qpos[arm.qadr] - home_q)))
        return {"primitive": "place", "at_home": bool(err < 0.02), "max_joint_error_rad": err}

    def pop_events():
        ev, S["events"] = S["events"], []
        return ev

    return {"name": "scripted manipulation", "start": start, "step": step, "done": done, "error": lambda: S["error"], "phase": lambda: S["phase"], "events": pop_events,
            "resume": lambda: None, "report": lambda: {"steps_done": S["i"], "error": S["error"], "task_text": S["ctx"].get("task_text"), "lift_rise_m": S["ctx"].get("lift_rise_m")}, "end_report": end_report, "recover": recover, "side": side, "pad_pose": lambda: arm.pad_pose(data), "arm": arm, "state": S}


# ----------------------------------------------------------------------------------------------------------
# Completion checker: sim ground truth
# ----------------------------------------------------------------------------------------------------------
def make_oracle_checker(model, data, world, pad_pose, side="left", task_cfg=TASK_CFG, success_cfg=SUCCESS_CFG, cfg=PICK_PLACE_CFG):
    """Builds the completion checker that reads the simulator's true state (the VLM checker replaces it; design plan 8 D4 item 1).

    Args:
        model (mujoco.MjModel): The task model.
        data (mujoco.MjData): The live state.
        world (WorldModel): The world model.
        pad_pose (callable): () -> (position, rotation) of the gripper's pad centre.
        side (str): The gripper's arm. Defaults to "left".
        task_cfg (dict): TASK_CFG, for the open finger travel. Defaults to it.
        success_cfg (dict): SUCCESS_CFG for the on-the-hotplate check. Defaults to it.
        cfg (dict): PICK_PLACE_CFG. Defaults to it.

    Returns:
        dict: {"name": "sim oracle", "check": check(segment, event, obs) -> {"passed", "reason", "details"}}. A pick is checked as "the beaker is held": the fingers stalled
        between the closed and the open travel and the beaker's middle within 2 cm of the pad centre; a place as "standing on the hotplate and the gripper open": the success
        check's footprint, height and upright tests (not the at-rest one: the check runs at the moment of the release) and the fingers open.
    """
    f1 = arm_ids(model, side)["finger_jnt"][0]
    fq = int(model.jnt_qposadr[f1])
    open_g = task_cfg.get("finger_open", 0.044)

    def check(segment, event, obs, decides=False):
        travel = float(data.qpos[fq])
        if segment["primitive"] == "pick":
            obj = segment["grounded"]["manipulated"]
            b = world.object_pose(obj)["position"].copy()
            b[2] += 0.5 * world.object_height(obj)
            p, _ = pad_pose()
            d = float(np.linalg.norm(b - p))
            lo, hi = cfg["held_travel_range_m"]
            ok = lo <= travel <= hi and d < 0.02
            return {"passed": bool(ok), "reason": "" if ok else f"the beaker is not held: finger travel {1000 * travel:.1f} mm, beaker {1000 * d:.0f} mm from the pad centre",
                    "details": {"finger_travel_m": travel, "beaker_to_pad_m": d}}
        ok_fp, diag = check_success(model, data, success_cfg)
        on_plate = all(diag[k]["ok"] for k in ("a_xy_in_footprint", "b_height", "c_upright"))
        opened = travel >= open_g - 0.003
        ok = on_plate and opened
        why = [] if on_plate else [f"the beaker is not standing on the hotplate ({ {k: v for k, v in diag.items() if not v['ok']} })"]
        if not opened:
            why.append(f"the gripper is not open (finger travel {1000 * travel:.1f} mm)")
        return {"passed": bool(ok), "reason": "; ".join(why), "details": {"finger_travel_m": travel, "success_diag": diag}}

    return {"name": "sim oracle", "check": check}
